/// <summary>
/// UPSPricingAttribute of table <c>InventTableModule</c> field PriceQty.
/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::Product, UPSPricingAttributeSourceLevel::Line)]
internal class UPSPricingAttributeInventTableModulePriceQty extends UPSPricingAttributeInventTableModule implements UPSIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(InventTableModule, PriceQty);
}

public Set getAllowedValues()
{
    InventTableModule   inventTableModule;
    var                 ret = new Set(Types::Real);

    while select PriceQty from inventTableModule
        group by PriceQty
    {
        if (!ret.in(inventTableModule.PriceQty))
        {
            ret.add(inventTableModule.PriceQty);
        }
    }

    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(InventTableModule, PriceQty));
    qbr.value(queryValue(_value));
}
